/**
 * Tipografías del PDF de dieta, embebidas como data URI.
 *
 * El PDF de referencia usa Times New Roman (cuerpo) y Calibri (pie), ambas de
 * Microsoft y no redistribuibles. Aquí van sus clones **métricamente
 * compatibles**: mismos anchos de glifo, así que los saltos de línea caen donde
 * caían.
 *
 *   Times New Roman -> Tinos    (SIL OFL 1.1, The Tinos Project Authors)
 *   Calibri         -> Carlito  (SIL OFL 1.1, The Carlito Project Authors)
 *
 * Subconjunto latino (U+0020-007E, U+00A0-00FF, U+0100-017F, comillas
 * tipográficas, EUR) en woff2. Unos 94 KB en binario, ~126 KB en base64 entre
 * las seis variantes.
 *
 * Embebidas y no servidas por red por la regla de "sin filesystem" y porque el
 * render debe ser hermético: una fuente que tarde o falle haría que el motor
 * pagine con una de reserva y el PDF saldría con otro diseño sin avisar.
 */

export const TINOS_REGULAR_WOFF2 =
  "data:font/woff2;base64,";

export const TINOS_BOLD_WOFF2 =
  "data:font/woff2;base64,";

export const TINOS_ITALIC_WOFF2 =
  "data:font/woff2;base64,";

export const TINOS_BOLD_ITALIC_WOFF2 =
  "data:font/woff2;base64,";

export const CARLITO_REGULAR_WOFF2 =
  "data:font/woff2;base64,";

export const CARLITO_BOLD_WOFF2 =
  "data:font/woff2;base64,";
